class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        a = []
        s = []
        t = []
        cu = None
        i = 0

        for num in nums:
            a.append(bin(num).count('1'))

        s = []
        t = []

        if len(nums) > 0:
            cu = a[0]
            i = 0

            while i < len(nums):
                if a[i] == cu:
                    import bisect
                    bisect.insort(t, nums[i])
                else:
                    cu = a[i]
                    s += t
                    t = []
                i += 1

            s += t

        return s == sorted(nums)
